import React, { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react';
import { createClient } from '@supabase/supabase-js';
import { 
  CommandeGros, CommandeSiteweb, CommandeMerch, Offre, InventoryItem, Charge, MarketingService as MarketingServiceType, MarketingSpend, Retour,
  CalculatedGros, CalculatedSiteweb, CalculatedMerch, CalculatedMarketing, DashboardData,
  GrosStatus, SitewebStatus, MerchStatus, OffreType, OffreCategory, MarketingStatus, MarketingSpendSource, MarketingSpendType,
  ChatMessage
} from './types.ts';

/**
 * ARCHITECTURE SPECIFICATION: Business Logic Layer
 */

async function hashPassword(password: string): Promise<string> {
  const msgUint8 = new TextEncoder().encode(password);
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

const computeGrosCalculatedFields = (item: CommandeGros) => {
  const total_cout = Number(item.prix_achat_article || 0) + Number(item.prix_impression || 0);
  const total_revenu = Number(item.prix_vente || 0);
  const benefice_net = total_revenu - total_cout;
  const marge_percent = total_revenu > 0 ? (benefice_net / total_revenu) * 100 : 0;
  return { ...item, total_cout, total_revenu, benefice_net, marge_percent };
};

const computeSitewebCalculatedFields = (item: CommandeSiteweb) => {
  const total_cout = Number(item.cout_article || 0) + Number(item.cout_impression || 0);
  const total_revenu = Number(item.prix_vente || 0);
  const benefice_net = total_revenu - (total_cout + Number(item.vendeur_benefice || 0));
  const marge_percent = total_revenu > 0 ? (benefice_net / total_revenu) * 100 : 0;
  return { ...item, total_cout, total_revenu, benefice_net, marge_percent };
};

const computeMerchCalculatedFields = (item: CommandeMerch): CalculatedMerch => {
  const profit = Number(item.prix_vente || 0) - Number(item.prix_achat || 0);
  let impact_encaisse = 0;
  let impact_attendu = 0;
  let impact_perte = 0;

  if (item.status === MerchStatus.LIVREE) {
    impact_encaisse = profit;
  } else if (item.status === MerchStatus.LIVREE_NON_ENCAISSEE) {
    impact_attendu = profit;
  } else if (item.status === MerchStatus.RETOUR) {
    impact_perte = Number(item.prix_achat || 0);
  }

  return { ...item, profit, impact_encaisse, impact_attendu, impact_perte };
};

const computeMarketingCalculatedFields = (item: MarketingServiceType) => {
  const benefice_net = Number(item.revenue || 0) - Number(item.client_charges || 0);
  return { ...item, benefice_net };
};

const computeInventoryCalculatedFields = (item: InventoryItem) => {
  const stock_value = Number(item.quantity || 0) * Number(item.unit_cost || 0);
  return { ...item, stock_value };
};

const SUPABASE_URL = (import.meta as any).env?.VITE_SUPABASE_URL || (window as any).process?.env?.VITE_SUPABASE_URL || '';
const SUPABASE_KEY = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || (window as any).process?.env?.VITE_SUPABASE_ANON_KEY || '';

const supabase = (SUPABASE_URL && SUPABASE_KEY) 
  ? createClient(SUPABASE_URL, SUPABASE_KEY) 
  : null;

interface AppState {
  gros: CommandeGros[];
  siteweb: CommandeSiteweb[];
  merch: CommandeMerch[];
  offres: Offre[];
  inventory: InventoryItem[];
  charges: Charge[];
  marketingServices: MarketingServiceType[];
  marketingSpends: MarketingSpend[];
  retours: Retour[];
  dashboardDateStart: string;
  dashboardDateEnd: string;
  isAuthenticated: boolean;
  isSyncing: boolean;
  isCloudActive: boolean;
  lastSynced: string | null;
  chatHistory: ChatMessage[];
  addChatMessage: (role: 'user' | 'assistant', text: string) => void;
  clearChat: () => void;
  login: (password: string) => Promise<boolean>;
  logout: () => void;
  setDashboardDateRange: (start: string, end: string) => void;
  updateGros: (id: string, field: keyof CommandeGros, value: any) => Promise<void>;
  addGros: () => Promise<void>;
  deleteGros: (id: string) => Promise<void>;
  importGros: (data: any[]) => Promise<void>;
  updateSiteweb: (id: string, field: keyof CommandeSiteweb, value: any) => Promise<void>;
  addSiteweb: () => Promise<void>;
  duplicateSiteweb: (id: string) => Promise<void>;
  deleteSiteweb: (id: string) => Promise<void>;
  importSiteweb: (data: any[]) => Promise<void>;
  updateMerch: (id: string, field: keyof CommandeMerch, value: any) => Promise<void>;
  addMerch: () => Promise<void>;
  deleteMerch: (id: string) => Promise<void>;
  importMerch: (data: any[]) => Promise<void>;
  getCalculatedGros: () => CalculatedGros[];
  getCalculatedSiteweb: () => CalculatedSiteweb[];
  getCalculatedMerch: () => CalculatedMerch[];
  getCalculatedMarketing: () => CalculatedMarketing[];
  getDashboardData: (startDate?: string, endDate?: string) => DashboardData;
  syncData: () => Promise<void>;
  updateOffre: (id: string, field: keyof Offre, value: any) => Promise<void>;
  addOffre: () => Promise<void>;
  deleteOffre: (id: string) => Promise<void>;
  importOffres: (data: any[]) => Promise<void>;
  updateInventory: (id: string, field: keyof InventoryItem, value: any) => Promise<void>;
  addInventory: () => Promise<void>;
  deleteInventory: (id: string) => Promise<void>;
  importInventory: (data: any[]) => Promise<void>;
  updateCharge: (id: string, field: keyof Charge, value: any) => Promise<void>;
  addCharge: (label?: string) => Promise<void>;
  deleteCharge: (id: string) => Promise<void>;
  importCharges: (data: any[]) => Promise<void>;
  updateMarketing: (id: string, field: keyof MarketingServiceType, value: any) => Promise<void>;
  addMarketing: () => Promise<void>;
  deleteMarketing: (id: string) => Promise<void>;
  updateMarketingSpend: (id: string, field: keyof MarketingSpend, value: any) => Promise<void>;
  addMarketingSpend: () => Promise<void>;
  deleteMarketingSpend: (id: string) => Promise<void>;
  addRetour: (reference: string) => Promise<void>;
  deleteRetour: (id: string) => Promise<void>;
}

const AppContext = createContext<AppState | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isCloudActive] = useState(!!supabase);
  const [lastSynced, setLastSynced] = useState<string | null>(null);
  const [isInitialLoaded, setIsInitialLoaded] = useState(false);

  const [gros, setGros] = useState<CommandeGros[]>([]);
  const [siteweb, setSiteweb] = useState<CommandeSiteweb[]>([]);
  const [merch, setMerch] = useState<CommandeMerch[]>([]);
  const [offres, setOffres] = useState<Offre[]>([]);
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [charges, setCharges] = useState<Charge[]>([]);
  const [marketingServices, setMarketingServices] = useState<MarketingServiceType[]>([]);
  const [marketingSpends, setMarketingSpends] = useState<MarketingSpend[]>([]);
  const [retours, setRetours] = useState<Retour[]>([]);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);

  const [dashboardDateStart, setDashboardDateStart] = useState<string>('');
  const [dashboardDateEnd, setDashboardDateEnd] = useState<string>('');

  const realtimeTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const fetchAllData = useCallback(async (isSilent = false) => {
    if (!supabase) {
      setIsInitialLoaded(true);
      return;
    }
    if (!isSilent) setIsSyncing(true);
    try {
      const [ { data: g }, { data: s }, { data: m_orders }, { data: o }, { data: i }, { data: c }, { data: m }, { data: ms }, { data: r } ] = await Promise.all([
        supabase.from('commandes_gros').select('*'),
        supabase.from('commandes_siteweb').select('*'),
        supabase.from('commandes_merch').select('*'),
        supabase.from('offres').select('*'),
        supabase.from('inventory').select('*'),
        supabase.from('charges').select('*'),
        supabase.from('marketing_services').select('*'),
        supabase.from('marketing_spends').select('*'),
        supabase.from('commandes_retours').select('*')
      ]);
      if (g) setGros(g); 
      if (s) setSiteweb(s); 
      if (m_orders) setMerch(m_orders);
      if (o) setOffres(o); 
      if (i) setInventory(i); 
      if (c) setCharges(c); 
      if (m) setMarketingServices(m); 
      if (ms) setMarketingSpends(ms);
      if (r) setRetours(r);
      setLastSynced(new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }));
    } catch (e) { 
      console.error("Supabase fetch error:", e); 
    } finally { 
      if (!isSilent) setIsSyncing(false); 
      setIsInitialLoaded(true);
    }
  }, []);

  // INITIAL FETCH & REALTIME SUBSCRIPTION
  useEffect(() => {
    fetchAllData();

    if (!supabase) return;

    // Supabase Realtime Strategy:
    // Listen to ALL relevant tables. On any event, trigger debounced global refresh.
    const tables = [
      'commandes_gros', 
      'commandes_siteweb', 
      'commandes_merch', 
      'offres', 
      'inventory', 
      'charges', 
      'marketing_services', 
      'marketing_spends',
      'commandes_retours'
    ];

    const channel = supabase.channel('merchdz_realtime');

    tables.forEach(table => {
      channel.on(
        'postgres_changes',
        { event: '*', schema: 'public', table },
        (payload) => {
          // Debounce logic to batch multiple rapid changes (1-3s delay target)
          if (realtimeTimeoutRef.current) clearTimeout(realtimeTimeoutRef.current);
          realtimeTimeoutRef.current = setTimeout(() => {
            fetchAllData(true);
          }, 750);
        }
      );
    });

    channel.subscribe();

    return () => {
      if (realtimeTimeoutRef.current) clearTimeout(realtimeTimeoutRef.current);
      supabase.removeChannel(channel);
    };
  }, [fetchAllData]);

  const login = useCallback(async (password: string) => {
    if (!supabase) return false;
    try {
      const inputHash = await hashPassword(password);
      const { data, error } = await supabase
        .from('app_settings')
        .select('password_hash')
        .eq('id', 'auth')
        .single();

      if (error || !data) return false;

      if (data.password_hash === inputHash) {
        setIsAuthenticated(true);
        return true;
      }
      return false;
    } catch (err) {
      return false;
    }
  }, []);

  const logout = useCallback(() => setIsAuthenticated(false), []);

  const setDashboardDateRange = useCallback((start: string, end: string) => {
    setDashboardDateStart(start);
    setDashboardDateEnd(end);
  }, []);

  const addChatMessage = useCallback((role: 'user' | 'assistant', text: string) => {
    setChatHistory(prev => [...prev, { id: crypto.randomUUID(), role, text }]);
  }, []);

  const clearChat = useCallback(() => setChatHistory([]), []);

  const syncData = useCallback(async () => {
    if (!supabase) return;
    setIsSyncing(true);
    try {
      await Promise.all([
        supabase.from('commandes_gros').upsert(gros.map(computeGrosCalculatedFields)),
        supabase.from('commandes_siteweb').upsert(siteweb.map(computeSitewebCalculatedFields)),
        supabase.from('commandes_merch').upsert(merch),
        supabase.from('offres').upsert(offres),
        supabase.from('inventory').upsert(inventory.map(computeInventoryCalculatedFields)),
        supabase.from('charges').upsert(charges),
        supabase.from('marketing_services').upsert(marketingServices.map(computeMarketingCalculatedFields)),
        supabase.from('marketing_spends').upsert(marketingSpends)
      ]);
      setLastSynced(new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }));
    } catch (e) { 
      console.error("Supabase manual sync error:", e); 
    } finally { 
      setIsSyncing(false); 
    }
  }, [gros, siteweb, merch, offres, inventory, charges, marketingServices, marketingSpends]);

  const updateGros = useCallback(async (id: string, field: keyof CommandeGros, value: any) => {
    let item: CommandeGros | undefined;
    setGros(p => p.map(i => {
      if (String(i.id) === String(id)) { item = { ...i, [field]: value }; return item; }
      return i;
    }));
    if (supabase && item) await supabase.from('commandes_gros').update(computeGrosCalculatedFields(item)).eq('id', id);
  }, []);

  const addGros = useCallback(async () => {
    const baseRecord = { reference: `G${Date.now()}`, client_name: '', client_phone: '', date_created: new Date().toISOString().split('T')[0], prix_achat_article: 0, impression: false, prix_impression: 0, prix_vente: 0, status: GrosStatus.EN_PRODUCTION, stock_note: '' };
    if (supabase) {
      const { data } = await supabase.from('commandes_gros').insert([computeGrosCalculatedFields(baseRecord as CommandeGros)]).select();
      if (data) setGros(p => p.some(o => o.id === data[0].id) ? p : [data[0], ...p]);
    } else {
      setGros(p => [{ ...baseRecord, id: crypto.randomUUID() } as CommandeGros, ...p]);
    }
  }, []);

  const updateSiteweb = useCallback(async (id: string, field: keyof CommandeSiteweb, value: any) => {
    let item: CommandeSiteweb | undefined;
    setSiteweb(p => p.map(i => {
      if (String(i.id) === String(id)) { item = { ...i, [field]: value }; return item; }
      return i;
    }));
    if (supabase && item) await supabase.from('commandes_siteweb').update(computeSitewebCalculatedFields(item)).eq('id', id);
  }, []);

  const addSiteweb = useCallback(async () => {
    const baseRecord = { reference: String(Date.now()).slice(-6), date_created: new Date().toISOString().split('T')[0], cout_article: 0, cout_impression: 0, prix_vente: 0, status: SitewebStatus.EN_LIVRAISON, stock_note: '', vendeur_name: 'V-X', vendeur_benefice: 0 };
    if (supabase) {
      const { data } = await supabase.from('commandes_siteweb').insert([computeSitewebCalculatedFields(baseRecord as CommandeSiteweb)]).select();
      if (data) setSiteweb(p => p.some(o => o.id === data[0].id) ? p : [data[0], ...p]);
    } else {
      setSiteweb(p => [{ ...baseRecord, id: crypto.randomUUID() } as CommandeSiteweb, ...p]);
    }
  }, []);

  const updateMerch = useCallback(async (id: string, field: keyof CommandeMerch, value: any) => {
    let item: CommandeMerch | undefined;
    setMerch(p => p.map(i => {
      if (String(i.id) === String(id)) { item = { ...i, [field]: value }; return item; }
      return i;
    }));
    if (supabase && item) await supabase.from('commandes_merch').update(item).eq('id', id);
  }, []);

  const addMerch = useCallback(async () => {
    const baseRecord = { reference: `M${Date.now()}`, client_name: '', produit: '', prix_achat: 0, prix_vente: 0, status: MerchStatus.EN_LIVRAISON, created_at: new Date().toISOString() };
    if (supabase) {
      const { data } = await supabase.from('commandes_merch').insert([baseRecord]).select();
      if (data) setMerch(prev => prev.some(o => o.id === data[0].id) ? prev : [data[0], ...prev]);
    } else {
      setMerch(p => [{ ...baseRecord, id: crypto.randomUUID() } as CommandeMerch, ...p]);
    }
  }, []);

  const deleteMerch = useCallback(async (id: string) => { 
    if (supabase) await supabase.from('commandes_merch').delete().eq('id', id); 
    setMerch(p => p.filter(i => String(i.id) !== String(id))); 
  }, []);

  const importMerch = useCallback(async (d: any[]) => {
    if (supabase) {
      const { data } = await supabase.from('commandes_merch').insert(d).select();
      if (data) {
        setMerch(prev => {
          const existingIds = new Set(prev.map(item => item.id));
          const newItems = data.filter(item => !existingIds.has(item.id));
          return [...newItems, ...prev];
        });
      }
    } else {
      const mapped = d.map(i => ({ ...i, id: crypto.randomUUID() }));
      setMerch(p => [...mapped, ...p]);
    }
  }, []);

  const updateInventory = useCallback(async (id: string, field: keyof InventoryItem, value: any) => {
    let item: InventoryItem | undefined;
    setInventory(p => p.map(i => {
      if (String(i.id) === String(id)) { item = { ...i, [field]: value }; return item; }
      return i;
    }));
    if (supabase && item) await supabase.from('inventory').update(computeInventoryCalculatedFields(item)).eq('id', id);
  }, []);

  const addInventory = useCallback(async () => {
    const baseRecord = { name: 'Nouveau Stock', sku: 'SKU-' + Date.now(), quantity: 0, min_stock: 5, unit_cost: 0, supplier: '' };
    if (supabase) {
      const { data } = await supabase.from('inventory').insert([computeInventoryCalculatedFields(baseRecord as InventoryItem)]).select();
      if (data) setInventory(p => p.some(o => o.id === data[0].id) ? p : [data[0], ...p]);
    } else {
      setInventory(p => [{ ...baseRecord, id: crypto.randomUUID() } as InventoryItem, ...p]);
    }
  }, []);

  const updateMarketing = useCallback(async (id: string, field: keyof MarketingServiceType, value: any) => {
    let item: MarketingServiceType | undefined;
    setMarketingServices(p => p.map(i => {
      if (String(i.id) === String(id)) { item = { ...i, [field]: value }; return item; }
      return i;
    }));
    if (supabase && item) await supabase.from('marketing_services').update(computeMarketingCalculatedFields(item)).eq('id', id);
  }, []);

  const addMarketing = useCallback(async () => {
    const baseRecord = { client_name: 'Nouveau Client', service_description: '', date: new Date().toISOString().split('T')[0], revenue: 0, client_charges: 0, status: MarketingStatus.EN_COURS };
    if (supabase) {
      const { data } = await supabase.from('marketing_services').insert([computeMarketingCalculatedFields(baseRecord as MarketingServiceType)]).select();
      if (data) setMarketingServices(p => p.some(o => o.id === data[0].id) ? p : [data[0], ...p]);
    } else {
      setMarketingServices(p => [{ ...baseRecord, id: crypto.randomUUID() } as MarketingServiceType, ...p]);
    }
  }, []);

  const updateOffre = useCallback(async (id: string, field: keyof Offre, value: any) => {
    setOffres(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i));
    if (supabase) await supabase.from('offres').update({ [field]: value }).eq('id', id);
  }, []);

  const addOffre = useCallback(async () => {
    const baseRecord = { date: new Date().toISOString().split('T')[0], type: OffreType.REVENUE, montant: 0, category: OffreCategory.OTHER, description: 'Nouveau Mouvement' };
    if (supabase) { 
      const { data } = await supabase.from('offres').insert([baseRecord]).select(); 
      if (data) setOffres(p => p.some(o => o.id === data[0].id) ? p : [data[0], ...p]); 
    } else {
      setOffres(p => [{ ...baseRecord, id: crypto.randomUUID() } as Offre, ...p]);
    }
  }, []);

  const deleteGros = useCallback(async (id: string) => { if (supabase) await supabase.from('commandes_gros').delete().eq('id', id); setGros(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const deleteSiteweb = useCallback(async (id: string) => { if (supabase) await supabase.from('commandes_siteweb').delete().eq('id', id); setSiteweb(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const deleteOffre = useCallback(async (id: string) => { if (supabase) await supabase.from('offres').delete().eq('id', id); setOffres(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const deleteInventory = useCallback(async (id: string) => { if (supabase) await supabase.from('inventory').delete().eq('id', id); setInventory(p => p.filter(i => String(i.id) !== String(id))); }, []);

  const updateCharge = useCallback(async (id: string, field: keyof Charge, value: any) => { 
    setCharges(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)); 
    if (supabase) await supabase.from('charges').update({ [field]: value }).eq('id', id); 
  }, []);

  const addCharge = useCallback(async (l: string = 'Autre') => { 
    const baseRecord = { date: new Date().toISOString().split('T')[0], label: l, montant: 0, note: '' }; 
    if (supabase) { 
      const { data } = await supabase.from('charges').insert([baseRecord]).select(); 
      if (data) setCharges(p => p.some(o => o.id === data[0].id) ? p : [data[0], ...p]); 
    } else {
      setCharges(p => [{ ...baseRecord, id: crypto.randomUUID() } as Charge, ...p]);
    }
  }, []);

  const deleteCharge = useCallback(async (id: string) => { if (supabase) await supabase.from('charges').delete().eq('id', id); setCharges(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const deleteMarketing = useCallback(async (id: string) => { if (supabase) await supabase.from('marketing_services').delete().eq('id', id); setMarketingServices(p => p.filter(i => String(i.id) !== String(id))); }, []);

  const updateMarketingSpend = useCallback(async (id: string, field: keyof MarketingSpend, value: any) => { 
    setMarketingSpends(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)); 
    if (supabase) await supabase.from('marketing_spends').update({ [field]: value }).eq('id', id); 
  }, []);

  const addMarketingSpend = useCallback(async () => { 
    const baseRecord = { date_start: new Date().toISOString().split('T')[0], date_end: new Date().toISOString().split('T')[0], source: MarketingSpendSource.GROS, type: MarketingSpendType.ADS, amount: 0, note: '' }; 
    if (supabase) { 
      const { data } = await supabase.from('marketing_spends').insert([baseRecord]).select(); 
      if (data) setMarketingSpends(p => p.some(o => o.id === data[0].id) ? p : [data[0], ...p]); 
    } else {
      setMarketingSpends(p => [{ ...baseRecord, id: crypto.randomUUID() } as MarketingSpend, ...p]);
    }
  }, []);

  const deleteMarketingSpend = useCallback(async (id: string) => { if (supabase) await supabase.from('marketing_spends').delete().eq('id', id); setMarketingSpends(p => p.filter(i => String(i.id) !== String(id))); }, []);

  const addRetour = useCallback(async (reference: string) => {
    if (supabase) {
      const { data, error } = await supabase
        .from('commandes_retours')
        .insert([{ order_reference: reference }])
        .select()
        .single();
      if (data && !error) setRetours(prev => [data, ...prev]);
    }
  }, []);

  const deleteRetour = useCallback(async (id: string) => {
    if (supabase) {
      const { error } = await supabase.from('commandes_retours').delete().eq('id', id);
      if (!error) setRetours(prev => prev.filter(r => r.id !== id));
    }
  }, []);

  const duplicateSiteweb = useCallback(async (id: string) => { 
    const t = siteweb.find(i => String(i.id) === String(id)); 
    if (t) { 
      const { id: _, ...baseRecord } = t;
      if (supabase) { 
        const { data } = await supabase.from('commandes_siteweb').insert([computeSitewebCalculatedFields({ ...baseRecord, reference: t.reference + '-copy' } as CommandeSiteweb)]).select(); 
        if (data) setSiteweb(p => p.some(o => o.id === data[0].id) ? p : [data[0], ...p]); 
      } else {
        setSiteweb(p => [{ ...baseRecord, reference: t.reference + '-copy', id: crypto.randomUUID() } as CommandeSiteweb, ...p]);
      }
    } 
  }, [siteweb]);

  const importGros = useCallback(async (d: any[]) => {
    if (supabase) {
      const { data } = await supabase.from('commandes_gros').insert(d.map(computeGrosCalculatedFields)).select();
      if (data) {
        setGros(prev => {
          const existingIds = new Set(prev.map(item => item.id));
          const newItems = data.filter(item => !existingIds.has(item.id));
          return [...newItems, ...prev];
        });
      }
    } else {
      setGros(p => [...d.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  const importSiteweb = useCallback(async (d: any[]) => {
    if (supabase) {
      const { data } = await supabase.from('commandes_siteweb').insert(d.map(computeSitewebCalculatedFields)).select();
      if (data) {
        setSiteweb(prev => {
          const existingIds = new Set(prev.map(item => item.id));
          const newItems = data.filter(item => !existingIds.has(item.id));
          return [...newItems, ...prev];
        });
      }
    } else {
      setSiteweb(p => [...d.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  const importOffres = useCallback(async (d: any[]) => {
    if (supabase) {
      const { data } = await supabase.from('offres').insert(d).select();
      if (data) {
        setOffres(prev => {
          const existingIds = new Set(prev.map(item => item.id));
          const newItems = data.filter(item => !existingIds.has(item.id));
          return [...newItems, ...prev];
        });
      }
    } else {
      setOffres(p => [...d.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  const importInventory = useCallback(async (d: any[]) => {
    if (supabase) {
      const { data } = await supabase.from('inventory').insert(d.map(computeInventoryCalculatedFields)).select();
      if (data) {
        setInventory(prev => {
          const existingIds = new Set(prev.map(item => item.id));
          const newItems = data.filter(item => !existingIds.has(item.id));
          return [...newItems, ...prev];
        });
      }
    } else {
      setInventory(p => [...d.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  const importCharges = useCallback(async (d: any[]) => {
    if (supabase) {
      const { data } = await supabase.from('charges').insert(d).select();
      if (data) {
        setCharges(prev => {
          const existingIds = new Set(prev.map(item => item.id));
          const newItems = data.filter(item => !existingIds.has(item.id));
          return [...newItems, ...prev];
        });
      }
    } else {
      setCharges(p => [...d.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  const getCalculatedGros = useCallback((): CalculatedGros[] => gros.map(i => {
    const calc = computeGrosCalculatedFields(i);
    return { 
      ...i, cost: calc.total_cout, 
      profit_encaisse: i.status === GrosStatus.LIVREE_ENCAISSE ? calc.benefice_net : 0, 
      profit_attendu: i.status === GrosStatus.LIVREE_NON_ENCAISSE ? calc.benefice_net : 0, 
      perte: i.status === GrosStatus.RETOUR ? calc.total_cout : 0 
    };
  }), [gros]);

  const getCalculatedSiteweb = useCallback((): CalculatedSiteweb[] => siteweb.map(i => ({ ...i, profit_net: computeSitewebCalculatedFields(i).benefice_net })), [siteweb]);

  const getCalculatedMerch = useCallback((): CalculatedMerch[] => merch.map(computeMerchCalculatedFields), [merch]);

  const getCalculatedMarketing = useCallback((): CalculatedMarketing[] => marketingServices.map(i => {
    const calc = computeMarketingCalculatedFields(i);
    return { ...i, net_profit: i.status === MarketingStatus.TERMINE ? calc.benefice_net : 0 };
  }), [marketingServices]);

  const getDashboardData = useCallback((startDate?: string, endDate?: string): DashboardData => {
    const cg = getCalculatedGros(); 
    const cs = getCalculatedSiteweb();
    const cm = getCalculatedMerch();
    const filter = (d: string) => (!startDate || d >= startDate) && (!endDate || d <= endDate);

    const fcg = cg.filter(i => filter(i.date_created)); 
    const fcs = cs.filter(i => filter(i.date_created));
    const fcm = cm.filter(i => filter(i.created_at));
    const fo = offres.filter(i => filter(i.date)); 
    const fc = charges.filter(i => filter(i.date)); 
    const fm = marketingSpends.filter(i => filter(i.date_start));

    const enc = fcg.reduce((a, c) => a + c.profit_encaisse, 0) + 
                fcs.filter(o => o.status === SitewebStatus.LIVREE).reduce((a, c) => a + c.profit_net, 0) +
                fcm.reduce((a, c) => a + c.impact_encaisse, 0);

    const att = fcg.reduce((a, c) => a + c.profit_attendu, 0) + 
                fcs.filter(o => o.status === SitewebStatus.LIVREE_NON_ENCAISSEE).reduce((a, c) => a + c.profit_net, 0) +
                fcm.reduce((a, c) => a + c.impact_attendu, 0);

    const per = fcg.reduce((a, c) => a + c.perte, 0) + 
                fcs.filter(o => o.status === SitewebStatus.RETOUR).reduce((a, c) => a + (Number(c.cout_article) + Number(c.cout_impression)), 0) +
                fcm.reduce((a, c) => a + c.impact_perte, 0);

    const no = fo.reduce((a, c) => c.type === OffreType.REVENUE ? a + Number(c.montant) : a - Number(c.montant), 0);
    const tc = fc.reduce((a, c) => a + Number(c.montant), 0); 
    const tm = fm.reduce((a, c) => a + Number(c.amount), 0);

    return { 
      encaisse_reel: enc, 
      profit_attendu: att, 
      pertes: per, 
      net_offres: no, 
      total_charges: tc, 
      total_marketing_spend: tm, 
      profit_net_final: enc + att + no - per - tc - tm 
    };
  }, [getCalculatedGros, getCalculatedSiteweb, getCalculatedMerch, offres, charges, marketingSpends]);

  return (
    <AppContext.Provider value={{ 
      gros, siteweb, merch, offres, inventory, charges, marketingServices, marketingSpends, retours, dashboardDateStart, dashboardDateEnd, setDashboardDateRange,
      isAuthenticated, login, logout, isSyncing, isCloudActive, lastSynced,
      chatHistory, addChatMessage, clearChat,
      updateGros, addGros, deleteGros, importGros, updateSiteweb, addSiteweb, duplicateSiteweb, deleteSiteweb, importSiteweb,
      updateMerch, addMerch, deleteMerch, importMerch,
      updateOffre, addOffre, deleteOffre, importOffres, updateInventory, addInventory, deleteInventory, importInventory,
      updateCharge, addCharge, deleteCharge, importCharges, updateMarketing, addMarketing, deleteMarketing,
      updateMarketingSpend, addMarketingSpend, deleteMarketingSpend, addRetour, deleteRetour,
      getCalculatedGros, getCalculatedSiteweb, getCalculatedMerch, getCalculatedMarketing, getDashboardData, syncData
    }}>
      {isInitialLoaded ? children : null}
    </AppContext.Provider>
  );
};

export const useAppStore = () => { 
  const c = useContext(AppContext); 
  if (!c) throw new Error("AppContext not found."); 
  return c; 
};

import React, { useState, useEffect, useRef } from 'react';
import { RotateCcw, Plus, Loader2, CheckCircle2, Trash2 } from 'lucide-react';
import { useAppStore } from '../store.tsx';

const Retour: React.FC = () => {
  const { retours, addRetour, deleteRetour, isSyncing } = useAppStore();
  const [scanValue, setScanValue] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [lastSaved, setLastSaved] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Always maintain focus on input when mode is active
  useEffect(() => {
    const focusInterval = setInterval(() => {
      if (isScanning && document.activeElement !== inputRef.current) {
        inputRef.current?.focus();
      }
    }, 500);
    return () => clearInterval(focusInterval);
  }, [isScanning]);

  // Handle Scan logic: Auto-save on change with stabilization (debounce)
  useEffect(() => {
    const trimmed = scanValue.trim();
    if (!trimmed || !isScanning || isProcessing) return;

    // Use a 400ms window for input to stabilize (finish scanner transmission)
    const saveTimeout = setTimeout(async () => {
      const referenceToSave = trimmed;

      // STEP 1: Immediate state reset to allow next scan while processing
      setScanValue(''); 
      setIsProcessing(true);

      try {
        await addRetour(referenceToSave);
        setLastSaved(referenceToSave);
        // Reset success indicator after 2s
        setTimeout(() => setLastSaved(null), 2000);
      } catch (err) {
        console.error("Save error:", err);
      } finally {
        setIsProcessing(false);
      }
    }, 400); 

    return () => clearTimeout(saveTimeout);
  }, [scanValue, isScanning, isProcessing, addRetour]);

  const handleDelete = async (id: string) => {
    if (!confirm('Supprimer ce retour ?')) return;
    await deleteRetour(id);
  };

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('fr-DZ', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight flex items-center gap-3">
            <RotateCcw className="text-blue-600" size={28} />
            Gestion des Retours
          </h2>
          <p className="text-slate-500 text-sm font-medium">Enregistrement rapide des retours par scan code-barres.</p>
        </div>

        <button 
          onClick={() => {
            setIsScanning(!isScanning);
            if (!isScanning) {
              setScanValue('');
              setTimeout(() => inputRef.current?.focus(), 100);
            }
          }}
          className={`flex items-center gap-2 px-6 py-3 rounded-2xl text-sm font-black transition-all shadow-xl shadow-blue-500/10 active:scale-95
            ${isScanning ? 'bg-emerald-600 text-white' : 'bg-blue-600 text-white'}`}
        >
          {isScanning ? <CheckCircle2 size={18} /> : <Plus size={18} />}
          {isScanning ? 'Mode Scan Actif' : 'Démarrer Scan'}
        </button>
      </div>

      {isScanning && (
        <div className="bg-slate-900 p-8 rounded-[2rem] border border-slate-800 shadow-2xl animate-in zoom-in-95 duration-300">
          <div className="max-w-xl mx-auto text-center space-y-6">
            <div className="flex items-center justify-center gap-4 text-emerald-400">
               {isProcessing ? <Loader2 className="animate-spin" size={20} /> : <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />}
               <span className="text-xs font-black uppercase tracking-widest">
                {isProcessing ? "Sauvegarde en cours..." : "Prêt pour le scan"}
               </span>
            </div>

            <div className="relative">
              <input 
                ref={inputRef}
                autoFocus
                type="text"
                value={scanValue}
                onChange={(e) => setScanValue(e.target.value)}
                placeholder="Scannez ici..."
                className="w-full bg-slate-800 border-2 border-slate-700 rounded-3xl px-6 py-5 text-2xl font-black text-white text-center outline-none focus:border-blue-500 transition-all placeholder:text-slate-600"
              />
              {lastSaved && (
                <div className="absolute -bottom-10 left-0 right-0 text-emerald-500 text-sm font-bold flex items-center justify-center gap-2 animate-in slide-in-from-top-2">
                  <CheckCircle2 size={16} />
                  Dernier scan enregistré: {lastSaved}
                </div>
              )}
            </div>

            <p className="text-slate-500 text-xs font-medium">L'enregistrement est automatique dès que le code est lu.</p>
          </div>
        </div>
      )}

      <div className="bg-white border border-slate-100 rounded-[2.5rem] shadow-sm overflow-hidden min-h-[400px]">
        <div className="p-6 border-b border-slate-50 bg-slate-50/30">
          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">Historique des Retours ({retours.length})</h3>
        </div>

        {isSyncing ? (
          <div className="p-20 flex flex-col items-center justify-center text-slate-400 gap-4">
             <Loader2 size={32} className="animate-spin" />
             <span className="text-xs font-bold uppercase tracking-widest">Mise à jour...</span>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  <th className="p-5">Référence Commande</th>
                  <th className="p-5">Date d'enregistrement</th>
                  <th className="p-5 text-center">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {retours.map((r) => (
                  <tr key={r.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="p-5 font-black text-slate-800 tracking-tight">{r.order_reference}</td>
                    <td className="p-5 text-sm font-medium text-slate-500">{formatDate(r.created_at)}</td>
                    <td className="p-5 text-center">
                      <button 
                        onClick={() => handleDelete(r.id)}
                        className="p-2 text-slate-200 hover:text-red-500 transition-colors rounded-xl hover:bg-red-50"
                      >
                        <Trash2 size={18} />
                      </button>
                    </td>
                  </tr>
                ))}
                {retours.length === 0 && (
                  <tr>
                    <td colSpan={3} className="p-20 text-center">
                       <div className="flex flex-col items-center gap-4 text-slate-300">
                          <RotateCcw size={48} />
                          <p className="text-xs font-black uppercase tracking-widest">Aucun retour enregistré</p>
                       </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

