                        className={`p-2 transition-all rounded-lg ${item.processed ? 'text-emerald-500 bg-emerald-50' : 'text-slate-300 hover:bg-slate-100'}`}
                        title={item.processed ? "Marquer comme non traité" : "Marquer comme traité"}
                      >
                        <ClipboardCheck size={16} />
                      </button>
                      <button onClick={(e) => handleDelete(e, item.id)} className="p-2 text-slate-300 hover:text-red-500 transition-all rounded-lg hover:bg-red-50">
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={analysisMode ? 8 : 7} className="p-20 text-center text-slate-400 font-bold uppercase tracking-widest text-xs">
                    <div className="flex flex-col items-center gap-4">
                      <Search size={48} className="text-slate-200" />
                      Aucune commande trouvée
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CommandesGros;

